import { FilterToggle } from "../HeritageFilterPanel/FilterToggle";
import { useTranslation } from "react-i18next";
import analyticsIcon from "../../assets/isons/logo_analitics.svg";

interface SpatialAnalyticsPanelProps {
  isOpen: boolean;
  onOpen: () => void;
  onClose: () => void;

  isHeatmapEnabled: boolean;
  onHeatmapChange: (enabled: boolean) => void;

  showLauncher: boolean;
}

export function SpatialAnalyticsPanel({
  isOpen,
  onOpen,
  onClose,
  isHeatmapEnabled,
  onHeatmapChange,
  showLauncher,
}: SpatialAnalyticsPanelProps) {

const { t } = useTranslation();

  if (!isOpen) {
     if (!showLauncher) {
    return null;
    }
    return (
      <button
        type="button"
        onClick={onOpen}
        className="
          absolute
          left-5
          top-64
          z-30

          flex
          h-16
          w-16
          items-center
          justify-center

          rounded-full
          bg-white

          shadow-[0_8px_15px_rgba(0,0,0,0.30)]

          transition-transform
          hover:scale-105
        "
      >
        <img
        src={analyticsIcon}
        alt=""
        className="h-full w-full p-2"
        />
      </button>
    );
  }

  return (
    <aside
      className="
        absolute
        left-0
        top-60
        z-30

        w-[335px]

        rounded-r-[22px]
        border-2
        border-accent
        bg-white/75

        px-7
        py-3
      "
    >
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <img
            src={analyticsIcon}
            alt=""
            className="h-12 w-12 shrink-0"
            />

          <h2 className="text-lg font-semibold">
            {t("spatialAnalytics.title")}
            </h2>
        </div>

        <button
          type="button"
          onClick={onClose}
          className="
            text-[42px]
            font-light
            leading-none
            text-accent
          "
        >
          ‹
        </button>
      </div>

      <div className="mt-10 flex items-start gap-5">
       <FilterToggle
        checked={isHeatmapEnabled}
        onChange={() =>
            onHeatmapChange(!isHeatmapEnabled)
        }
        />

        <div>
          <div className="text-lg">
             {t("spatialAnalytics.heatmap")}
          </div>

          <div className="mt-2 text-xs leading-snug">
            {t("spatialAnalytics.heatmapDescription")}
          </div>
        </div>
      </div>
    </aside>
  );
}