import {
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
  Tooltip,
} from "recharts";

import { useTranslation } from "react-i18next";

import { HERITAGE_LEGEND } from "../../config/heritageLegendConfig";

import {
  HERITAGE_TYPE_GROUPS,
  resolveHeritageTypeGroup,
} from "../../config/heritageTypeConfig";

import { HeritageFeatureCollection } from "../../types/heritageObj/HeritageFeatureCollection";

interface HeritageAnalyticsChartProps {
  data: HeritageFeatureCollection;
}

export function HeritageAnalyticsChart({
  data,
}: HeritageAnalyticsChartProps) {
  const { t } = useTranslation();

  const statusData = HERITAGE_LEGEND
    .map((item) => ({
      id: item.id,
      name: t(item.translationKey),
      value: data.features.filter((feature) =>
        item.matches(feature.properties),
      ).length,
      color: item.color,
    }))
    .filter((item) => item.value > 0);

  const typeData = HERITAGE_TYPE_GROUPS
    .map((item) => ({
      id: item.id,
      name: t(item.translationKey),
      value: data.features.filter(
        (feature) =>
          resolveHeritageTypeGroup(
            feature.properties.objType,
          ) === item.id,
      ).length,
      color: item.color,
    }))
    .filter((item) => item.value > 0);

  return (
    <div className="h-[190px] w-full">
      <ResponsiveContainer
        width="100%"
        height="100%"
      >
        <PieChart>
          {/* INNER RING — STATUS */}

          <Pie
            data={statusData}
            dataKey="value"
            nameKey="name"
            cx="50%"
            cy="50%"
            innerRadius={0}
            outerRadius={52}
            stroke="#ffffff"
            strokeWidth={1}
          >
            {statusData.map((item) => (
              <Cell
                key={item.id}
                fill={item.color}
              />
            ))}
          </Pie>

          {/* OUTER RING — TYPE */}

          <Pie
            data={typeData}
            dataKey="value"
            nameKey="name"
            cx="50%"
            cy="50%"
            innerRadius={58}
            outerRadius={78}
            stroke="#ffffff"
            strokeWidth={1}
          >
            {typeData.map((item) => (
              <Cell
                key={item.id}
                fill={item.color}
              />
            ))}
          </Pie>

          <Tooltip />
        </PieChart>
      </ResponsiveContainer>
    </div>
  );
}