import { HeatmapLayer } from "@deck.gl/aggregation-layers";
import { centroid } from "@turf/turf";
import { HERITAGE_LEGEND } from "../config/heritageLegendConfig";

import type {
  HeritageFeature,
  HeritageFeatureCollection,
} from "../types/heritageObj/HeritageFeatureCollection";

interface HeritageHeatmapPoint {
  position: [number, number];
  weight: number;
}

function featureToHeatmapPoint(
  feature: HeritageFeature
): HeritageHeatmapPoint | null {
  if (!feature.geometry) {
    return null;
  }

  // Якщо об'єкт уже є Point — використовуємо його координати напряму
  if (feature.geometry.type === "Point") {
    return {
      position: feature.geometry.coordinates as [number, number],
      weight: 1,
    };
  }

  // Для Polygon / MultiPolygon / інших геометрій
  // використовуємо centroid
  const center = centroid(feature as any);

  return {
    position: center.geometry.coordinates as [number, number],
    weight: 1,
  };
}

export function createHeritageHeatmapLayer(
  heritageData: HeritageFeatureCollection
) {
  const heatmapData = heritageData.features
    .filter((feature) =>
      HERITAGE_LEGEND.some((item) =>
        item.matches(feature.properties)
      )
    )
    .map(featureToHeatmapPoint)
    .filter(
      (point): point is HeritageHeatmapPoint =>
        point !== null
    );

  return new HeatmapLayer<HeritageHeatmapPoint>({
    id: "heritage-heatmap",

    data: heatmapData,

    getPosition: (d) => d.position,
    getWeight: (d) => d.weight,

    aggregation: "SUM",

    radiusPixels: 45,
    intensity: 1,
    threshold: 0.05,
    opacity: 0.7,

    colorRange: [
      [255, 255, 178],
      [254, 217, 118],
      [254, 178, 76],
      [253, 141, 60],
      [240, 59, 32],
      [189, 0, 38],
    ],
  });
}